"""티켓 번호 구간 배정 - 호출부의 인스턴스 락이 구간 선택과 다음 번호 갱신을 함께 보호한다."""

from threading import Lock


class TicketRanges:
    def __init__(self, start: int = 0) -> None:
        self._next = int(start)
        self._lock = Lock()

    def reserve(self, count: int) -> range:
        count = int(count)
        if count < 0:
            raise ValueError("count must be nonnegative")
        with self._lock:
            return self._take_range(count)

    def _take_range(self, count: int) -> range:
        start = self._next
        stop = start + count
        result = range(start, stop)
        self._next = stop
        return result

