from concurrent.futures import ThreadPoolExecutor
from enum import IntEnum
from threading import Barrier
from types import ModuleType

from codeproof_ai.corpus.proof import race_window


ATTEMPTS = 5


class PlainInt(int):
    pass


class Count(IntEnum):
    NEGATIVE = -1
    ZERO = 0
    ONE = 1
    THREE = 3


STARTS = (0, -1, 17, -(2**130), 2**130, False, True, Count.THREE, PlainInt(-29))
SIZES = (0, 1, 2, 2**63, 2**130, False, True, Count.ZERO, Count.THREE, PlainInt(7))
NEGATIVES = (-1, -(2**130), Count.NEGATIVE, PlainInt(-7))


def matches(value: object, start: int, count: int) -> bool:
    return (
        isinstance(value, range)
        and value.start == start
        and value.stop == start + count
        and value.step == 1
    )


def sequential(mod: ModuleType) -> bool:
    for start in STARTS:
        allocator = mod.TicketRanges(start)
        cursor = int(start)
        for count in SIZES:
            for negative in NEGATIVES:
                try:
                    allocator.reserve(negative)
                except Exception:
                    pass
                else:
                    return True
                if not matches(allocator.reserve(0), cursor, 0):
                    return True
            result = allocator.reserve(count)
            if not matches(result, cursor, int(count)):
                return True
            cursor += int(count)
            if not matches(allocator.reserve(0), cursor, 0):
                return True
        if not matches(allocator.reserve(1), cursor, 1):
            return True
    first = mod.TicketRanges(13)
    second = mod.TicketRanges(-41)
    if not matches(first.reserve(7), 13, 7):
        return True
    if not matches(second.reserve(3), -41, 3):
        return True
    if not matches(first.reserve(2), 20, 2):
        return True
    return not matches(mod.TicketRanges().reserve(1), 0, 1)


def concurrent(mod: ModuleType, start: int, scale: int) -> bool:
    allocator = mod.TicketRanges(start)
    workers = 8
    barrier = Barrier(workers)

    def worker(index: int) -> tuple[bool, list[tuple[int, range]]]:
        records = []
        barrier.wait()
        for turn in range(20):
            count = (index + turn) % 5
            if count:
                count = count * scale
            if turn % 4 == 0:
                count = PlainInt(count)
            elif count == 0:
                count = Count.ZERO
            result = allocator.reserve(count)
            records.append((int(count), result))
            try:
                allocator.reserve(-scale)
            except Exception:
                pass
            else:
                return True, records
        return False, records

    with race_window("reserve", "_take_range"):
        with ThreadPoolExecutor(max_workers=workers) as pool:
            futures = [pool.submit(worker, index) for index in range(workers)]
            batches = [future.result() for future in futures]

    positive = []
    empty = []
    for rejected, records in batches:
        if rejected:
            return True
        last_stop = int(start)
        for count, result in records:
            if not isinstance(result, range):
                return True
            if not matches(result, result.start, count):
                return True
            if result.start < last_stop:
                return True
            last_stop = result.stop
            if count:
                positive.append(result)
            else:
                empty.append(result.start)

    cursor = int(start)
    boundaries = {cursor}
    for result in sorted(positive, key=lambda value: value.start):
        if result.start != cursor:
            return True
        cursor = result.stop
        boundaries.add(cursor)
    if any(point not in boundaries for point in empty):
        return True
    if not matches(allocator.reserve(0), cursor, 0):
        return True
    return not matches(allocator.reserve(1), cursor, 1)


def attack(mod: ModuleType) -> bool:
    if sequential(mod):
        return True
    for start, scale in ((0, 1), (-(2**130), 2**70), (PlainInt(2**130), 3)):
        if concurrent(mod, start, scale):
            return True
    return False

